     rmap_cells m /\ poison_cells m
  /\ rw_cells asegs m 0xaf710 [C8 (Z_to_bv 64 0xb15e0)] /\ rw_cells asegs m 0xb15e0 [C8 (Z_to_bv 64 0x19227)]
